					if(type == 1) return String(CharArray::of(0x7B, 0x30, 0x7D, 0x2C, 0x20, 0x7B, 0x31, 0x7D));
					if(type == 2) return String(CharArray::of(0x7B, 0x30, 0x7D, 0x2C, 0x20, 0x7B, 0x31, 0x7D));
